import { useEffect, useRef, useState } from 'react'
import { AccessibilityInfo, Animated, Easing, StyleSheet, View } from 'react-native'
import Svg, { Circle, Path } from 'react-native-svg'
import { renk } from './tema'

/**
 * Karsilama ekranindaki CHECK-IN SAHNESI.
 *
 * "Hesap oluştur" dugmesinin hemen ustunde duruyor ve uygulamanin tek
 * vaadini tek karede anlatiyor: ortada bir check-in noktasi, cevresinde
 * o an orada olan insanlar. Igne nabiz gibi atiyor - turuncu burada
 * dekorasyon degil "canlilik" tasiyor, kimlik kuralina uygun kullanim
 * budur.
 *
 * Kullanicinin karari (2026-08-30): once yalniz bir nabiz isareti
 * konmustu; ardindan kullanici referans bir gorsel gonderip cevresinde
 * insan halkalari da olmasini istedi.
 *
 * SOKAK IZGARASI BILEREK YOK. Referans gorselde acik renkli bir kroki
 * zemini vardi; buraya alinmadi cunku (a) `KrokiZemin` tam bu yuzden
 * 2026-08-27'de kaldirilmisti - cizilmis bir sokak izgarasi "burasi
 * neresi" sorusunu aciyor ve kullanici henuz giris yapmadigi icin
 * cevabi yok, (b) zemindeki sicaklik lekeleri zaten nefes aliyor ve
 * ikinci bir doku onlarla catisirdi.
 *
 * INSAN HALKALARI KIMLIK TASIMIYOR: hepsi ayni genel siluet, sayi
 * uydurulmuyor, ad yazilmiyor. Kaldirilan ornek check-in kartlari
 * uydurma mekan adi ve uydurma kisi sayisi tasidigi icin kalkmisti;
 * burada oyle bir iddia yok.
 *
 * "Hareketi azalt" aciksa halkalar HIC atmiyor; sahne duragan bir
 * resim gibi duruyor.
 */

/** Bir nabiz halkasinin disari acilip sonme suresi. CanliHarita ile ayni. */
const NABIZ_SURESI = 2600

/** Ayni anda kac nabiz halkasi acilir. */
const HALKA_SAYISI = 3

/** Sahnenin yuksekligi. Dugme ile dort baslik arasindaki bosluga oturuyor. */
const YUKSEKLIK = 200

/** Nabiz halkalarinin en genis capi. */
const NABIZ_CAPI = 176

/**
 * Insan halkalari: [yatay yuzde, dikey konum, cap].
 *
 * Yatay konum yuzde cunku sahne ekranin tam genisligini kapliyor ve
 * kenardakiler bilerek TASIYOR - kadraj devam ediyormus hissi veriyor.
 */
const INSANLAR: readonly (readonly [number, number, number])[] = [
  [16, 96, 58],
  [84, 100, 58],
  [-2, 140, 50],
  [102, 140, 50],
]

/** Disari dogru acilip sonen tek bir nabiz halkasi. */
function NabizHalkasi({ gecikme }: { gecikme: number }) {
  const ilerleme = useRef(new Animated.Value(0)).current

  useEffect(() => {
    const dongu = Animated.loop(
      Animated.timing(ilerleme, {
        toValue: 1,
        duration: NABIZ_SURESI,
        delay: gecikme,
        easing: Easing.out(Easing.quad),
        useNativeDriver: true,
      })
    )
    dongu.start()
    return () => dongu.stop()
  }, [gecikme, ilerleme])

  return (
    <Animated.View
      style={[
        stiller.nabiz,
        {
          opacity: ilerleme.interpolate({ inputRange: [0, 1], outputRange: [0.3, 0] }),
          transform: [
            { scale: ilerleme.interpolate({ inputRange: [0, 1], outputRange: [0.26, 1] }) },
          ],
        },
      ]}
    />
  )
}

/** Cevredeki insanlardan biri: halka icinde genel bir siluet. */
function InsanHalkasi({ yuzde, ust, cap }: { yuzde: number; ust: number; cap: number }) {
  return (
    <View
      style={[
        stiller.insan,
        {
          left: `${yuzde}%`,
          top: ust,
          width: cap,
          height: cap,
          borderRadius: cap / 2,
          marginLeft: -cap / 2,
        },
      ]}
    >
      <Svg width={cap * 0.62} height={cap * 0.62} viewBox="0 0 24 24">
        <Circle cx={12} cy={8.6} r={4} fill={renk.turuncu} fillOpacity={0.45} />
        <Path
          d="M3.6 21.4c0-4.7 3.8-7.8 8.4-7.8s8.4 3.1 8.4 7.8z"
          fill={renk.turuncu}
          fillOpacity={0.45}
        />
      </Svg>
    </View>
  )
}

export function CheckInSahnesi() {
  const [hareketVar, setHareketVar] = useState(false)

  useEffect(() => {
    AccessibilityInfo.isReduceMotionEnabled().then((azalt) => setHareketVar(!azalt))
  }, [])

  return (
    <View
      style={stiller.sahne}
      pointerEvents="none"
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
    >
      {/* Nabiz, merkezdeki ignenin arkasinda. */}
      <View style={stiller.nabizAlani}>
        {hareketVar ? (
          Array.from({ length: HALKA_SAYISI }, (_, i) => (
            <NabizHalkasi key={i} gecikme={(NABIZ_SURESI / HALKA_SAYISI) * i} />
          ))
        ) : (
          <View style={[stiller.nabiz, { opacity: 0.2, transform: [{ scale: 0.55 }] }]} />
        )}
      </View>

      {INSANLAR.map(([yuzde, ust, cap], i) => (
        <InsanHalkasi key={i} yuzde={yuzde} ust={ust} cap={cap} />
      ))}

      {/* Ikinci, kucuk igne: sahneyi tek merkezli olmaktan cikariyor -
          "baska yerlerde de var" demek icin. */}
      <View style={stiller.kucukIgne}>
        <Svg width={22} height={22} viewBox="0 0 24 24">
          <Path
            d="M12 2.5a7.2 7.2 0 0 0-7.2 7.2c0 5.4 7.2 11.8 7.2 11.8s7.2-6.4 7.2-11.8A7.2 7.2 0 0 0 12 2.5z"
            fill={renk.turuncu}
          />
          <Circle cx={12} cy={9.6} r={2.7} fill={renk.karsilamaZemini} />
        </Svg>
      </View>

      {/* Merkezdeki check-in ignesi. Ozellik listesindeki 'konum'
          ikonuyla ayni cizim - ekranda iki farkli igne olmasin. */}
      <View style={stiller.merkezIgne}>
        <Svg width={62} height={62} viewBox="0 0 24 24">
          <Path
            d="M12 2.5a7.2 7.2 0 0 0-7.2 7.2c0 5.4 7.2 11.8 7.2 11.8s7.2-6.4 7.2-11.8A7.2 7.2 0 0 0 12 2.5z"
            fill={renk.turuncu}
          />
          <Circle cx={12} cy={9.6} r={2.7} fill={renk.karsilamaZemini} />
        </Svg>
      </View>
    </View>
  )
}

const stiller = StyleSheet.create({
  sahne: { height: YUKSEKLIK, width: '100%' },

  nabizAlani: {
    position: 'absolute',
    left: '50%',
    top: 96,
    width: NABIZ_CAPI,
    height: NABIZ_CAPI,
    marginLeft: -NABIZ_CAPI / 2,
    marginTop: -NABIZ_CAPI / 2,
    alignItems: 'center',
    justifyContent: 'center',
  },
  nabiz: {
    position: 'absolute',
    width: NABIZ_CAPI,
    height: NABIZ_CAPI,
    borderRadius: NABIZ_CAPI / 2,
    borderWidth: 2,
    borderColor: renk.turuncu,
  },

  insan: {
    position: 'absolute',
    borderWidth: 2,
    borderColor: renk.turuncu,
    backgroundColor: renk.karsilamaZemini,
    alignItems: 'center',
    justifyContent: 'center',
    overflow: 'hidden',
  },

  merkezIgne: {
    position: 'absolute',
    left: '50%',
    top: 62,
    marginLeft: -31,
  },

  kucukIgne: {
    position: 'absolute',
    left: '66%',
    top: 40,
  },
})

